"""Connection handling for the usage writer.

`execute(op, connect, settings=None)` performs one write against the system of record. `connect(dsn)`
is the injected connector: it returns a connection object whose `run(op)` performs the write and
returns the stored row id, or raises.

On a `TransientConnectionError` the write path opens a fresh connection to the same endpoint and
re-issues the operation, up to `db.reconnect_attempts` attempts in total. Other exceptions go
straight through.
"""
import time

from .settings import load_settings


class TransientConnectionError(Exception):
    """Raised by the driver when a connection drops in the middle of an operation."""


def primary_dsn(settings=None):
    """The endpoint the write path uses: the system of record."""
    if settings is None:
        settings = load_settings()
    return (settings.get("db") or {})["primary"]


def execute(op, connect, settings=None):
    """Perform one write, reconnecting on a transient drop.

    Opens a connection to `db.primary` and issues the operation. If the driver raises
    `TransientConnectionError`, opens a fresh connection to the same endpoint and re-issues, up to
    `db.reconnect_attempts` attempts in total. Between attempts the path waits `db.backoff_ms`.
    Any other exception propagates on first occurrence. If the attempt budget is exhausted, the
    last `TransientConnectionError` propagates so the caller records the operation as failed.
    """
    if settings is None:
        settings = load_settings()
    db_settings = settings.get("db") or {}
    attempts = db_settings.get("reconnect_attempts", 1)
    backoff_s = (db_settings.get("backoff_ms", 0) or 0) / 1000.0
    dsn = primary_dsn(settings)
    for attempt in range(attempts):
        try:
            connection = connect(dsn)
            return connection.run(op)
        except TransientConnectionError:
            if attempt + 1 >= attempts:
                raise
            if backoff_s > 0:
                time.sleep(backoff_s)

